draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';

  // draw kale
  ctx.fillStyle = 'green';
  ctx.beginPath();
  ctx.arc(W/2, H/2, 50, 0, 2*Math.PI);
  ctx.fill();
  ctx.stroke();

  // draw nutrient bubbles
  for (let i = 0; i < 5; i++) {
    ctx.fillStyle = 'blue';
    ctx.beginPath();
    ctx.arc(W/2 + 70*Math.cos(t + i), H/2 + 70*Math.sin(t + i), 10, 0, 2*Math.PI);
    ctx.fill();
    ctx.stroke();
  }

  // draw stick figure
  ctx.fillStyle = 'black';
  ctx.beginPath();
  ctx.arc(W/2 - 100, H/2 - 50, 20, 0, 2*Math.PI);
  ctx.fill();
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 - 100, H/2 - 30);
  ctx.lineTo(W/2 - 100, H/2 + 50);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 - 100, H/2);
  ctx.lineTo(W/2 - 120, H/2 + 20);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 - 100, H/2);
  ctx.lineTo(W/2 - 80, H/2 + 20);
  ctx.stroke();

  ctx.restore();
}
